def findLoops(A):
    res = _findLoops(A)
    if __name__ == "__main__":
        try:
            print(("\n".join(res)))
        except IOError as e:
            if e.errno == 32:
                exit()
    else:
        funcOut = {}
        for r in res:
            r = r.split()
            if r[0] not in funcOut:
                funcOut[r[0]] = []
            funcOut[r[0]].append([int(r[1]), int(r[2]), r[3:]])

        return funcOut

