def _calculate_divergence(qry_seq, trg_seq):
    if not qry_seq or not trg_seq:
        return 0.0

    curr_del = 0
    curr_ins = 0

    match_count = 0
    mis_count = 0
    del_count = 0
    ins_count = 0

    for q, t in zip(qry_seq, trg_seq):
        if q == t:
            match_count += 1
            if curr_del != 0:
                del_count += 1
                curr_del = 0
            if curr_ins != 0:
                ins_count += 1
                curr_ins = 0
        elif q == "-" and t != "-":
            curr_del += 1
            if curr_ins != 0:
                ins_count += 1
                curr_ins = 0
        elif q != "-" and t == "-":
            curr_ins += 1
            if curr_del != 0:
                del_count += 1
                curr_del = 0
        elif q != t:
            mis_count += 1
            if curr_del != 0:
                del_count += 1
                curr_del = 0
            if curr_ins != 0:
                ins_count += 1
                curr_ins = 0
        else:
            raise Exception("No alignment conditions fit, {0} {1}".format(q, t))
    if curr_del != 0:
        del_count += 1
        curr_del = 0
    if curr_ins != 0:
        ins_count += 1
        curr_ins = 0

    indel_sim_rate = 0.0
    total = match_count + mis_count + del_count + ins_count
    if total != 0:
        indel_sim_rate = match_count / float(total)
    return 1 - indel_sim_rate

def get_peak_sequences(adata, genome):

    genome = SeqIO.to_dict(SeqIO.parse(genome, format="fasta"))

    tmp = []
    for row in adata.var.to_dict("records"):

        try:
            seq = get_sequence(chrom=row["chr"], start=row["start"], end=row["stop"], genome=genome)
        except KeyError:
            seq = np.nan

        tmp.append(seq)

    adata.var["seq"] = tmp

def _calc_total_reads(self, locus_start, locus_end):
  def _calc(samp_read_depth):
    # We estimate 7 heterozygous SNPs per 10 kb, which goes as input to CNA
    # algorithms. Thus, we determine how many SNPs are equivalent to a region
    # of the given size, then weight accordingly.
    assert locus_start < locus_end
    # Figure out approximately equivalent number of SSMs to this region.
    equiv_ssms = (locus_end - locus_start) * self._hetsnp_rate
    return int(np.round(equiv_ssms * samp_read_depth))

  D = [_calc(self._read_depth[sampidx]) for sampidx in self._sampidxs]
  return self._cap_cnv_D(D)

def integrate(self, x):
    [z_mean, z_log_var, z] = self.encoder_z.predict(x)
    return z_mean

def _find_ref_and_variant_nt(self, variant):
