def get_INFO_dict_from_INFO_string_corrected(INFO):

    info = get_INFO_dict_from_INFO_string(INFO)
    if any({not k.startswith("INFO_") for k in info}): raise ValueError("info is not correct")
    info = {k.split("INFO_")[1] : v for k,v in info.items()}

    return info

def _fatal_errors(jerr):
    if jerr == 7777:
        raise ValueError(
            "All predictors have zero variance " "(glmnet error no. 7777)."
        )

    if jerr == 10000:
        raise ValueError(
            "At least one value of relative_penalties must be "
            "positive (glmnet error no. 10000)."
        )

    if jerr == 90000:
        raise ValueError("Solver did not converge (glmnet error no. 90000).")

    if jerr < 7777:
        raise RuntimeError(
            "Memory allocation error (glmnet error no. {}).".format(jerr)
        )

    if jerr > 8000 and jerr < 9000:
        k = jerr - 8000
        raise ValueError("Probability for class {} close to 0.".format(k))

    if jerr > 9000:
        k = jerr - 9000
        raise ValueError("Probability for class {} close to 1.".format(k))

    else:
        raise RuntimeError("Fatal glmnet error no. {}.".format(jerr))

def __call__(self, y_true, y_pred):
    anchor, positive, negative = tf.unstack(y_pred)
    return K.mean(K.maximum(chebyshev_distance(anchor, positive) - chebyshev_distance(anchor, negative) + self.margin, 0))

def calc_reference_sas(
    adata: ad.AnnData,
    batch_effect: str = "dataset_name",
    cell_ontology: str = "cell_ontology_class",
    similarity: typing.Callable = _identity,
):
    neighbors_propotion = []
    n = len(adata.obs[batch_effect].unique())
    for x in adata.obs[batch_effect].unique():
        propotion = 0
        for i in adata.obs[cell_ontology].unique():
            neighbors = 0
            own_neighbors = 0
            for j in adata.obs[cell_ontology].unique():
                own_neighbors += (
                    similarity(i, j)
                    * (
                        (adata.obs[cell_ontology] == j) & (adata.obs[batch_effect] == x)
                    ).sum()
                )
                neighbors += similarity(i, j) * (adata.obs[cell_ontology] == j).sum()

            propotion += (
                own_neighbors
                / neighbors
                * (
                    (adata.obs[cell_ontology] == i) & (adata.obs[batch_effect] == x)
                ).sum()
            )

        propotion = propotion / (adata.obs[batch_effect] == x).sum()
        neighbors_propotion.append(propotion)
    neighbors_propotion = np.mean(neighbors_propotion)
    return 1 - (neighbors_propotion - 1 / n) / (1 - 1 / n)

def _convergence_errors(jerr):
    if jerr < -20000:
        k = abs(20000 + jerr)
        warnings.warn(
            "Predicted probability close to 0 or 1 for " "lambda no. {}.".format(k),
            RuntimeWarning,
        )

    if jerr > -20000 and jerr < -10000:
        # This indicates the number of non-zero coefficients in a model
        # exceeded a user-specified bound. We don't expose this parameter to
        # the user, so there is not much sense in exposing the error either.
        warnings.warn("Non-fatal glmnet error no. {}.".format(jerr), RuntimeWarning)

    if jerr > -10000:
        warnings.warn(
            "Model did not converge for smaller values of lambda, "
            "returning solution for the largest {} values.".format(-1 * (jerr - 1)),
            RuntimeWarning,
        )

def get_scorer(scoring):
    if isinstance(scoring, six.string_types):
        try:
            scorer = SCORERS[scoring]
        except KeyError:
            raise ValueError(
                "%r is not a valid scoring value. "
                "Valid options are %s" % (scoring, sorted(SCORERS.keys()))
            )
    else:
        scorer = scoring
    return scorer

def cl_accuracy(
    cl_dag: utils.CellTypeDAG,
    source: np.ndarray,
    target: np.ndarray,
    ref_cl_list: typing.List[str],  # a list of unique cl in ref
) -> pd.DataFrame:
    if len(source) != len(target):
        raise ValueError("Invalid input: different cell number.")
    positive_cl = []
    negative_cl = []
    for query_cl in np.unique(source):
        for ref_cl in ref_cl_list:
            if cl_dag.is_related(query_cl, ref_cl):
                positive_cl.append(query_cl)
                break
        else:
            negative_cl.append(query_cl)

    # sensitivity
    accuracy_dict = {}
    ref_cl_set = {cl_dag.get_vertex(item) for item in ref_cl_list}
    for query_cl in positive_cl:
        target_cl = target[source == query_cl]
        cl_accuracy = np.zeros(target_cl.size)
        cache = {}  # avoid repeated computation
        for i, _target_cl in enumerate(target_cl):
            if _target_cl in cache:
                cl_accuracy[i] = cache[_target_cl]
                continue
            if cl_dag.is_descendant_of(_target_cl, query_cl):
                cache[_target_cl] = 1  # equal or descendant results as 1
            elif cl_dag.is_ancestor_of(_target_cl, query_cl):
                intermediates = set.intersection(
                    set(
                        cl_dag.graph.bfsiter(
                            cl_dag.get_vertex(query_cl), mode=igraph.OUT
                        )
                    ),
                    set(
                        cl_dag.graph.bfsiter(
                            cl_dag.get_vertex(_target_cl), mode=igraph.IN
                        )
                    ),
                )
                cache[_target_cl] = np.mean(
                    [
                        len(list(cl_dag.graph.bfsiter(intermediate, mode=igraph.IN)))
                        / len(
                            list(
                                cl_dag.graph.bfsiter(
                                    cl_dag.get_vertex(_target_cl), mode=igraph.IN
                                )
                            )
                        )
                        for intermediate in intermediates
                        if ref_cl_set.intersection(
                            set(cl_dag.graph.bfsiter(intermediate, mode=igraph.IN))
                        )
                    ]
                )
            else:
                cache[_target_cl] = 0
            cl_accuracy[i] = cache[_target_cl]
        accuracy_dict[query_cl] = [cl_accuracy.size, cl_accuracy.mean(), True]

    # specificity
    for query_cl in negative_cl:
        target_cl = target[source == query_cl]
        cl_accuracy = np.in1d(target_cl, ["rejected", "unassigned"])
        accuracy_dict[query_cl] = [cl_accuracy.size, cl_accuracy.mean(), False]

    return pd.DataFrame(accuracy_dict, index=("cell number", "accuracy", "positive")).T

