def novel_from_reads(best_lead, other_leads, klen, skip, skip_repetitive, debug=False):
    consensus_min = 2
    maxshift = klen
    minspan = 0.2
    minalns = 0.25
    minident = 0.5
    minident_abs = 5
    minbestdiff = 3

    alignments = []
    anchors = {}
    taboo = set()
    for i, kmer in iter_kmers(best_lead.seq, klen=klen, skip=skip_repetitive):
        if kmer in taboo:
            continue
        if kmer in anchors:
            del anchors[kmer]
            taboo.add(kmer)
            continue
        anchors[kmer] = i

    for leadi, lead in enumerate(other_leads):
        last_i = None
        last_j = None
        conseq = ""
        span = 0
        for j, kmer in iter_kmers(lead.seq, klen=klen, skip=skip):
            if kmer not in anchors:
                continue
            i = anchors[kmer]
            if abs(i - j) > maxshift:
                continue
            if last_i is not None and i <= last_i:
                continue

            if last_i is None:
                if j > 0:
                    conseq = "-" * i
            else:
                fwd_i = i - last_i
                fwd_j = j - last_j
                if len(conseq) + fwd_j > len(best_lead.seq):
                    fwd_j = len(best_lead.seq) - len(conseq)

                if fwd_i == fwd_j and fwd_j > 0:
                    span += (j - last_j)
                    m = 0
                    for l in range(1, (j - last_j) + 1):
                        if lead.seq[last_j + l] == best_lead.seq[last_i + l]:
                            m += 1
                    ident = m / float((j - last_j))
                    if ident >= minident:
                        conseq += lead.seq[last_j:j][:fwd_j]
                    else:
                        conseq += "-" * (fwd_j)
                else:
                    conseq += "-" * (fwd_j)
            last_i = i
            last_j = j

        if len(conseq) < len(best_lead.seq):
            conseq += "-" * (len(best_lead.seq) - len(conseq))

        conseq_new = []
        h = 0
        while h < len(best_lead.seq):
            if conseq[h] == "-":
                conseq_new.append("-")
                h += 1
            else:
                buffer = []
                ident = 0
                while h < len(best_lead.seq) and conseq[h] != "-":
                    ident += (best_lead.seq[h] == conseq[h])
                    buffer.append(conseq[h])
                    h += 1
                if ident / float(len(buffer)) > minident and ident > minident_abs:
                    conseq_new.append("".join(buffer))
                else:
                    conseq_new.append("-" * len(buffer))
        conseq = "".join(conseq_new)

        if span / float(len(best_lead.seq)) > minspan:
            alignments.append(conseq)

    maxal = 1
    for i in range(len(best_lead.seq)):
        maxal = max(maxal, len([best_lead.seq[i]] + [a[i] for a in alignments if not a[i] in "^_"]))
    maxal = float(maxal)

    flattened = ""
    for i in range(len(best_lead.seq)):
        al = [a[i] for a in alignments if not a[i] == "-"]
        if len(al) < consensus_min or len(al) / maxal < minalns:
            flattened += best_lead.seq[i]
        else:
            top = util.most_common([best_lead.seq[i]] + al)
            if len(top) > 1 and top[0][0] - top[1][0] >= minbestdiff:
                flattened += top[0][1]
            else:
                flattened += best_lead.seq[i]

            # if top[0][0]/float(len(al)+1) < 0.75:
            #    flattened+=best_lead.seq[i]
            # else:
            #    flattened+=top[0][1]

    # print("FLT",flattened)
    # if debug:
    #    print("B",best_lead.seq)
    #    for o in other_leads:
    #        print("O",o.seq)
    #    print("F",flattened)
    #    print("=====")
    return flattened

def model_card(self) -> ModelCard:
    """The model card for this model."""
    return self._model_card

def _to_model_card(self) -> ModelCard:
    # define tags
    tags = [
        "biology",
        "genomics",
        "single-cell",
        _SCVI_HUB.MODEL_CLS_NAME_TAG.format(self.model_cls_name),
        _SCVI_HUB.SCVI_VERSION_TAG.format(self.scvi_version),
        _SCVI_HUB.ANNDATA_VERSION_TAG.format(self.anndata_version),
    ]
    for m in self.data_modalities:
        tags.append(_SCVI_HUB.MODALITY_TAG.format(m))
    for t in self.tissues:
        tags.append(_SCVI_HUB.TISSUE_TAG.format(t))
    if self.data_is_annotated is not None:
        tags.append(_SCVI_HUB.ANNOTATED_TAG.format(self.data_is_annotated))

    # define the card data, which is the header
    card_data = ModelCardData(
        license=self.license_info,
        library_name=_SCVI_HUB.HF_LIBRARY_NAME,
        tags=tags,
    )

    # flatten the model_init_params into a single dict
    # for example {'kwargs': {'model_kwargs': {'foo': 'bar'}}, 'non_kwargs': {'n_hidden': 128,
    # 'n_latent': 10}}
    # becomes {'n_hidden': 128, 'n_latent': 10, 'foo': 'bar'}
    if "non_kwargs" in self.model_init_params.keys():
        non_kwargs = self.model_init_params["non_kwargs"]
        kwargs = self.model_init_params["kwargs"]
    else:
        non_kwargs = {
            k: v for k, v in self.model_init_params.items() if not isinstance(v, dict)
        }
        kwargs = {k: v for k, v in self.model_init_params.items() if isinstance(v, dict)}
    kwargs = {k: v for (i, j) in kwargs.items() for (k, v) in j.items()}
    # kwargs and non_kwargs keys should be disjoint but if not, we'll just use the original
    # model_init_params
    if len(set(kwargs.keys()).intersection(set(non_kwargs.keys()))) == 0:
        flattened_model_init_params = {**non_kwargs, **kwargs}
    else:
        flattened_model_init_params = self.model_init_params

    # create the content from the template
    content = template.format(
        card_data=card_data.to_yaml(),
        description=self.description,
        model_init_params=json.dumps(flattened_model_init_params, indent=4),
        model_setup_anndata_args=json.dumps(self.model_setup_anndata_args, indent=4),
        model_summary_stats=AnnDataManager._view_summary_stats(
            self.model_summary_stats, as_markdown=True
        ),
        model_data_registry=AnnDataManager._view_data_registry(
            self.model_data_registry, as_markdown=True
        ),
        model_parent_module=self.model_parent_module,
        data_is_minified=_SCVI_HUB.DEFAULT_MISSING_FIELD
        if self.data_is_minified is None
        else self.data_is_minified,
        training_data_url=self.training_data_url or _SCVI_HUB.DEFAULT_NA_FIELD,
        training_code_url=self.training_code_url or _SCVI_HUB.DEFAULT_NA_FIELD,
        references=self.references,
    )

    # finally create and return the actual card
    return ModelCard(content)

def _calc_read_counts(self, variant):
  normal = variant.genotype('NORMAL')
  tumor = variant.genotype('TUMOUR')

  reference_nt, variant_nt = self._find_ref_and_variant_nt(variant)
  tumor_reads = {
    'forward': {
      'A': int(tumor['FAZ']),
      'C': int(tumor['FCZ']),
      'G': int(tumor['FGZ']),
      'T': int(tumor['FTZ']),
    },
    'reverse': {
      'A': int(tumor['RAZ']),
      'C': int(tumor['RCZ']),
      'G': int(tumor['RGZ']),
      'T': int(tumor['RTZ']),
    },
  }

  ref_reads = tumor_reads['forward'][reference_nt] + tumor_reads['reverse'][reference_nt]
  # For now, variant reads are defined as only the non-reference nucleotide in
  # the inferred tumor SNP. We ignore reads of a third or fourth base.
  variant_reads = tumor_reads['forward'][variant_nt] + tumor_reads['reverse'][variant_nt]
  total_reads = ref_reads + variant_reads

  return (ref_reads, total_reads)

def __call__(self, loss):
    if not hasattr(self, 'layer'):
        raise Exception('Need to call `set_layer` on '
                        'ActivityRegularizer instance '
                        'before calling the instance.')
    regularized_loss = loss
    for i in range(len(self.layer.inbound_nodes)):
        output = K.sigmoid(0.1 * self.layer.get_output_at(i))
        #output = self.layer.get_output_at(i)
        p_hat = K.mean(K.abs(output))
        regularized_loss += self.l * kl_divergence(self.p, p_hat)
    return K.in_train_phase(regularized_loss, loss)

def get_motif_from_weights(weights):
    idx = weights.argmax(axis=0)
    return ''.join([ALPHABET_R[i] for i in idx])

